const b = $input.first().json.body || {};
const m = String(b.date || '').match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
const now = new Date();
const d = m ? new Date(+m[1], +m[2]-1, +m[3]) : new Date(now.getFullYear(), now.getMonth(), now.getDate());
const openHour  = Number(b.from_hour ?? 9);
const closeHour = Number(b.to_hour ?? 18);
const start = new Date(d); start.setHours(0,0,0,0);
const end = new Date(start); end.setDate(end.getDate()+1);
return [{ json: { label: start.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}),
                  openHour, closeHour,
                  timeMin: start.toISOString(), timeMax: end.toISOString() } }];

const meta = $('Window').first().json;
const day = new Date(meta.timeMin);
const open  = new Date(day); open.setHours(meta.openHour, 0, 0, 0);
const close = new Date(day); close.setHours(meta.closeHour, 0, 0, 0);

const busy = $input.all()
  .filter(i => i.json && i.json.start && i.json.start.dateTime)
  .map(i => ({ s: new Date(i.json.start.dateTime), e: new Date(i.json.end.dateTime) }))
  .sort((a, b) => a.s - b.s);

const fmt = t => t.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
const slots = [];
let cursor = open;
for (const b of busy) {
  if (b.s > cursor) {
    const until = b.s < close ? b.s : close;
    if (until - cursor >= 15 * 60000) slots.push(`${fmt(cursor)} to ${fmt(until)}`);
  }
  if (b.e > cursor) cursor = b.e;
}
if (cursor < close && close - cursor >= 15 * 60000) slots.push(`${fmt(cursor)} to ${fmt(close)}`);

return [{ json: { day: meta.label, free: slots, count: slots.length,
                  window: `${meta.openHour}:00-${meta.closeHour}:00` } }];
